// Extract and validate input text
const inputText = $input.item.json.text || $input.item.json.body?.text;
const language = $input.item.json.language || 'en';
const analysisTypes = $input.item.json.analysis_types || ['sentiment', 'entities', 'topics', 'summarization'];

if (!inputText) {
  throw new Error('No text provided for analysis');
}

if (inputText.length < 10) {
  throw new Error('Text too short for meaningful analysis (minimum 10 characters)');
}

if (inputText.length > 50000) {
  throw new Error('Text too long (maximum 50,000 characters)');
}

return {
  json: {
    text: inputText,
    language: language,
    analysis_types: analysisTypes,
    text_length: inputText.length,
    word_count: inputText.split(/\s+/).length,
    request_id: `nlp_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    timestamp: new Date().toISOString()
  }
};

