parameters.functionCode:
// Aggregate all NLP analysis results
const items = $input.all();

// Get base data from validate node
const baseData = items.find(item => item.json.request_id)?.json;

// Extract Hugging Face sentiment
const hfSentiment = items.find(item => item.json.label);
const hfResult = hfSentiment ? {
  provider: 'huggingface',
  sentiment: hfSentiment.json.label?.toLowerCase(),
  score: hfSentiment.json.score
} : null;

// Extract Google Cloud NLP sentiment
const googleSentiment = items.find(item => item.json.documentSentiment);
const googleSentimentResult = googleSentiment ? {
  provider: 'google_nlp',
  sentiment: googleSentiment.json.documentSentiment.score > 0.25 ? 'positive' : 
             googleSentiment.json.documentSentiment.score < -0.25 ? 'negative' : 'neutral',
  score: googleSentiment.json.documentSentiment.score,
  magnitude: googleSentiment.json.documentSentiment.magnitude
} : null;

// Extract OpenAI sentiment
const openaiSentiment = items.find(item => {
  try {
    const content = item.json.choices?.[0]?.message?.content;
    if (content) {
      const parsed = JSON.parse(content);
      return parsed.sentiment !== undefined;
    }
  } catch (e) {}
  return false;
});
const openaiSentimentResult = openaiSentiment ? (() => {
  const parsed = JSON.parse(openaiSentiment.json.choices[0].message.content);
  return {
    provider: 'openai_gpt4',
    sentiment: parsed.sentiment,
    score: parsed.score,
    confidence: parsed.confidence,
    explanation: parsed.explanation
  };
})() : null;

// Extract Google Cloud NLP entities
const googleEntities = items.find(item => item.json.entities);
const entitiesResult = googleEntities ? {
  provider: 'google_nlp',
  entities: googleEntities.json.entities.slice(0, 20).map(e => ({
    name: e.name,
    type: e.type,
    salience: e.salience,
    mentions: e.mentions?.length || 0
  }))
} : null;

// Extract OpenAI topics
const openaiTopics = items.find(item => {
  try {
    const content = item.json.choices?.[0]?.message?.content;
    if (content) {
      const parsed = JSON.parse(content);
      return parsed.topics !== undefined;
    }
  } catch (e) {}
  return false;
});
const topicsResult = openaiTopics ? (() => {
  const parsed = JSON.parse(openaiTopics.json.choices[0].message.content);
  return {
    provider: 'openai_gpt4',
    topics: parsed.topics,
    keywords: parsed.keywords,
    categories: parsed.categories
  };
})() : null;

// Extract OpenAI summary
const openaiSummary = items.find(item => {
  try {
    const content = item.json.choices?.[0]?.message?.content;
    return content && !content.includes('{') && content.length < 500;
  } catch (e) {}
  return false;
});
const summaryResult = openaiSummary ? {
  provider: 'openai_gpt4',
  summary: openaiSummary.json.choices[0].message.content.trim()
} : null;

// Calculate consensus sentiment
const sentiments = [hfResult, googleSentimentResult, openaiSentimentResult].filter(Boolean);
const sentimentCounts = {};
sentiments.forEach(s => {
  sentimentCounts[s.sentiment] = (sentimentCounts[s.sentiment] || 0) + 1;
});
const consensusSentiment = Object.entries(sentimentCounts)
  .sort((a, b) => b[1] - a[1])[0]?.[0] || 'neutral';

const avgScore = sentiments
  .filter(s => typeof s.score === 'number')
  .reduce((sum, s) => sum + s.score, 0) / sentiments.filter(s => typeof s.score === 'number').length;

// Build final analysis object
const analysis = {
  request_id: baseData?.request_id,
  timestamp: baseData?.timestamp,
  input: {
    text_preview: baseData?.text.substring(0, 200) + '...',
    text_length: baseData?.text_length,
    word_count: baseData?.word_count,
    language: baseData?.language
  },
  sentiment_analysis: {
    consensus: {
      sentiment: consensusSentiment,
      score: parseFloat(avgScore.toFixed(3)),
      confidence: sentiments.length >= 2 ? 'high' : 'medium',
      provider_agreement: `${sentimentCounts[consensusSentiment] || 0}/${sentiments.length}`
    },
    providers: sentiments
  },
  entity_extraction: entitiesResult,
  topic_classification: topicsResult,
  text_summary: summaryResult,
  metadata: {
    providers_used: [
      hfResult ? 'huggingface' : null,
      googleSentimentResult || googleEntities ? 'google_nlp' : null,
      openaiSentimentResult || openaiTopics || openaiSummary ? 'openai_gpt4' : null
    ].filter(Boolean),
    analysis_duration_ms: Date.now() - new Date(baseData?.timestamp).getTime()
  }
};

return {
  json: analysis
};
